import math

def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()

def build_agent(sandbox):
    return sandbox.get_seeker_body()

def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {'last_tx': 0.0, 'last_ty': 0.0, 'tvx': 0.0, 'tvy': 0.0}
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Exponential smoothing for target velocity estimation
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        alpha = 0.2  # Smoothing factor for exponential smoothing
        dx = tx - state['last_tx']
        dy = ty - state['last_ty']
        state['tvx'] = alpha * dx / dt + (1 - alpha) * state['tvx']
        state['tvy'] = alpha * dy / dt + (1 - alpha) * state['tvy']
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Define target position for navigation
    if step_count < 110:
        gx, gy = 11.95, 1.35
    elif in_slot:
        gx, gy = tx, ty
    else:
        gx = 13.1 if (step_count // 120) % 2 == 0 else 13.5
        gy = 1.35

    # Calculate forces
    if in_slot:
        # Determine reference direction for heading alignment
        target_speed = math.sqrt(state['tvx']**2 + state['tvy']**2)
        if target_speed >= 0.15:
            reference_dir = (state['tvx'], state['tvy'])
        else:
            reference_dir = (tx - sx, ty - sy)
        reference_angle = math.atan2(reference_dir[1], reference_dir[0])
        current_heading = sandbox.get_seeker_heading()
        angle_diff = abs(current_heading - reference_angle)

        # Check if heading needs correction
        if angle_diff > math.radians(55):
            # Prioritize heading alignment
            fx = 300.0 * (gx - sx) + 60.0 * reference_dir[0]
            fy = 300.0 * (gy - sy) + 60.0 * reference_dir[1]
        else:
            # Reduce relative velocity
            relative_vx = state['tvx'] - svx
            relative_vy = state['tvy'] - svy
            fx = 300.0 * (gx - sx) - 60.0 * relative_vx
            fy = 300.0 * (gy - sy) - 60.0 * relative_vy
    else:
        fx = 300.0 * (gx - sx) - 60.0 * svx
        fy = 180.0 * (gy - sy) - 45.0 * svy

    # Avoid thrust cooldown by clamping to 90 N
    mag = math.sqrt(fx**2 + fy**2)
    if mag > 90.0:
        fx, fy = fx * 90.0 / mag, fy * 90.0 / mag

    sandbox.apply_seeker_force(fx, fy)
